// ProjectServiceServer is the server API for ProjectService service.
// All implementations must embed UnimplementedProjectServiceServer
// for forward compatibility.
//
// ProjectService exposes bounded, tenant-scoped project work. The caller's
// principal and tenant authority are derived from authenticated context; the
// optional ScopeContext is a requested scope that the server must verify.
type ProjectServiceServer interface {
	// P1A disposition: OUT; project membership administration is beyond the Phase 1 surface.
	GetProjectMembership(context.Context, *GetProjectMembershipRequest) (*GetProjectMembershipResponse, error)
	// P1A disposition: OUT; project membership administration is beyond the Phase 1 surface.
	ListProjectMembers(context.Context, *ListProjectMembersRequest) (*ListProjectMembersResponse, error)
	// P1A disposition: OUT; project membership administration is beyond the Phase 1 surface.
	InviteProjectMember(context.Context, *InviteProjectMemberRequest) (*MutateProjectMembershipResponse, error)
	// P1A disposition: OUT; project membership administration is beyond the Phase 1 surface.
	AcceptProjectInvitation(context.Context, *AcceptProjectInvitationRequest) (*MutateProjectMembershipResponse, error)
	// P1A disposition: OUT; project membership administration is beyond the Phase 1 surface.
	ChangeProjectMemberRole(context.Context, *ChangeProjectMemberRoleRequest) (*MutateProjectMembershipResponse, error)
	// P1A disposition: OUT; project membership administration is beyond the Phase 1 surface.
	RevokeProjectMember(context.Context, *RevokeProjectMemberRequest) (*MutateProjectMembershipResponse, error)
	// P1A disposition: OUT; project membership administration is beyond the Phase 1 surface.
	TransferProjectOwnership(context.Context, *TransferProjectOwnershipRequest) (*MutateProjectMembershipResponse, error)
	// P1A disposition: OUT; this Phase 3 project-management method is not part of the Phase 1 surface.
	// Reads one currently authorized project summary.
	GetProject(context.Context, *GetProjectRequest) (*GetProjectResponse, error)
	// P1A disposition: OUT; this Phase 3 project-management method is not part of the Phase 1 surface.
	// Lists only projects currently admitted to the caller, in bounded pages.
	ListProjects(context.Context, *ListProjectsRequest) (*ListProjectsResponse, error)
	// P1A disposition: OUT; this Phase 3 project-management method is not part of the Phase 1 surface.
	// Creates an active project with its own stable identity and timezone.
	CreateProject(context.Context, *CreateProjectRequest) (*CreateProjectResponse, error)
	// P1A disposition: OUT; project settings are not part of the Phase 1 surface.
	// Updates project name and timezone under an exact project revision.
	UpdateProjectSettings(context.Context, *UpdateProjectSettingsRequest) (*UpdateProjectSettingsResponse, error)
	// P1A disposition: OUT; project lifecycle management is not part of the Phase 1 surface.
	// Archives an owned project without deleting task or audit history.
	ArchiveProject(context.Context, *SetProjectLifecycleRequest) (*SetProjectLifecycleResponse, error)
	// P1A disposition: OUT; project lifecycle management is not part of the Phase 1 surface.
	// Restores an archived owned project under an exact revision fence.
	RestoreProject(context.Context, *SetProjectLifecycleRequest) (*SetProjectLifecycleResponse, error)
	// P1A disposition: OUT; this Phase 3 project-management method is not part of the Phase 1 surface.
	// Creates one ordinary task under the project's currently published
	// workflow configuration.
	CreateTask(context.Context, *CreateTaskRequest) (*CreateTaskResponse, error)
	// P1A disposition: OUT; this Phase 3 project-management method is not part of the Phase 1 surface.
	// Reads one currently authorized task.
	GetTask(context.Context, *GetTaskRequest) (*GetTaskResponse, error)
	// P1A disposition: OUT; this Phase 3 project-management method is not part of the Phase 1 surface.
	// Lists a bounded page of currently authorized tasks for a project.
	ListTasks(context.Context, *ListTasksRequest) (*ListTasksResponse, error)
	// P1A disposition: OUT; project task search is not part of the Phase 1 surface.
	// Searches current project tasks. Free-text search is unavailable until the
	// index can revalidate each result; exact predicates remain available.
	SearchTasks(context.Context, *SearchTasksRequest) (*SearchTasksResponse, error)
	// P1A disposition: OUT; this Phase 3 project-management method is not part of the Phase 1 surface.
	// Moves one task under exact task and workflow revisions. An optional typed
	// lane field edit is committed atomically with the status transition.
	MoveTask(context.Context, *MoveTaskRequest) (*MoveTaskResponse, error)
	// P1A disposition: OUT; this Phase 3 project-management method is not part of the Phase 1 surface.
	// Revises sparse project-owned task details under exact task/workflow revisions.
	PatchTask(context.Context, *PatchTaskRequest) (*PatchTaskResponse, error)
	// P1A disposition: OUT; this Phase 3 project-management method is not part of the Phase 1 surface.
	// Retains an archived task and its complete activity history.
	ArchiveTask(context.Context, *ArchiveTaskRequest) (*ArchiveTaskResponse, error)
	// P1A disposition: OUT; this Phase 3 project-management method is not part of the Phase 1 surface.
	// Restores an archived task under an exact revision fence.
	RestoreTask(context.Context, *RestoreTaskRequest) (*RestoreTaskResponse, error)
	// P1A disposition: OUT; this Phase 3 project-management method is not part of the Phase 1 surface.
	// Creates or updates an author-owned workflow draft under an exact revision.
	SaveWorkflowDraft(context.Context, *SaveWorkflowDraftRequest) (*SaveWorkflowDraftResponse, error)
	// P1A disposition: OUT; this Phase 3 project-management method is not part of the Phase 1 surface.
	// Reloads an authorized draft without inferring its contents from board cards.
	GetWorkflowDraft(context.Context, *GetWorkflowDraftRequest) (*GetWorkflowDraftResponse, error)
	// P1A disposition: OUT; this Phase 3 project-management method is not part of the Phase 1 surface.
	// Validates a named draft and previews its exact impact without publishing.
	PreviewWorkflowDraft(context.Context, *PreviewWorkflowDraftRequest) (*PreviewWorkflowDraftResponse, error)
	// P1A disposition: OUT; this Phase 3 project-management method is not part of the Phase 1 surface.
	// Publishes the exact reviewed workflow digest and creates a new immutable
	// project workflow version.
	PublishWorkflowDraft(context.Context, *PublishWorkflowDraftRequest) (*PublishWorkflowDraftResponse, error)
	// P1A disposition: OUT; this Phase 3 project-management method is not part of the Phase 1 surface.
	// Reads the current published status, field, and transition configuration.
	GetWorkflowConfiguration(context.Context, *GetWorkflowConfigurationRequest) (*GetWorkflowConfigurationResponse, error)
	// P1A disposition: OUT; this Phase 3 project-management method is not part of the Phase 1 surface.
	// Saves a personal or project-audience view. The view never widens task
	// authorization; every board read rechecks task access.
	SaveBoardView(context.Context, *SaveBoardViewRequest) (*SaveBoardViewResponse, error)
	// P1A disposition: OUT; this Phase 3 project-management method is not part of the Phase 1 surface.
	// Lists bounded saved views that the current project member may read.
	ListBoardViews(context.Context, *ListBoardViewsRequest) (*ListBoardViewsResponse, error)
	// P1A disposition: OUT; this Phase 3 project-management method is not part of the Phase 1 surface.
	// Reads a bounded page of authorized cards for one project view. No total
	// task count is returned; the opaque cursor is bound to caller, view and
	// project revisions.
	GetBoard(context.Context, *GetBoardRequest) (*GetBoardResponse, error)
	// P1A disposition: OUT; this Phase 3 project-management method is not part of the Phase 1 surface.
	// Adds an allowlisted typed link to a task. A reference does not grant
	// access to its chat or document target.
	AddTaskLink(context.Context, *AddTaskLinkRequest) (*AddTaskLinkResponse, error)
	// P1A disposition: OUT; this Phase 3 project-management method is not part of the Phase 1 surface.
	// Resolves links against current target authorization, returning a neutral
	// restricted state for both inaccessible and absent targets.
	ListTaskLinks(context.Context, *ListTaskLinksRequest) (*ListTaskLinksResponse, error)
	// P1A disposition: OUT; reverse task-link lookup is a Phase 3 project operation.
	// Reverse link read: the live tasks that link one workflow run (journey)
	// or work item, limited to projects the caller may read. Tasks in other
	// projects are omitted, not reported.
	ListTaskLinksByTarget(context.Context, *ListTaskLinksByTargetRequest) (*ListTaskLinksByTargetResponse, error)
	// P1A disposition: OUT; task-link removal is a Phase 3 project operation.
	// Tombstones a typed task link under exact task revision and idempotency
	// fences. The target is retained only as an audit reference and is no longer
	// resolved or returned by ListTaskLinks.
	RemoveTaskLink(context.Context, *RemoveTaskLinkRequest) (*RemoveTaskLinkResponse, error)
	// P1A disposition: OUT; this Phase 3 project-management method is not part of the Phase 1 surface.
	// Adds a sanitized comment to one authorized task.
	AddTaskComment(context.Context, *AddTaskCommentRequest) (*AddTaskCommentResponse, error)
	// P1A disposition: OUT; this Phase 3 project-management method is not part of the Phase 1 surface.
	// Corrects one comment under an exact revision fence.
	EditTaskComment(context.Context, *EditTaskCommentRequest) (*EditTaskCommentResponse, error)
	// P1A disposition: OUT; this Phase 3 project-management method is not part of the Phase 1 surface.
	// Tombstones one comment under an exact revision fence.
	DeleteTaskComment(context.Context, *DeleteTaskCommentRequest) (*DeleteTaskCommentResponse, error)
	// P1A disposition: OUT; this Phase 3 project-management method is not part of the Phase 1 surface.
	// Reads a bounded page of current comment revisions for one authorized task.
	ListTaskComments(context.Context, *ListTaskCommentsRequest) (*ListTaskCommentsResponse, error)
	// P1A disposition: OUT; this Phase 3 project-management method is not part of the Phase 1 surface.
	// Reads a bounded page of ordered comment activity for one authorized task.
	ListTaskActivity(context.Context, *ListTaskActivityRequest) (*ListTaskActivityResponse, error)
	mustEmbedUnimplementedProjectServiceServer()
}

